import{_ as e,o as s,c as t,a2 as o}from"./chunks/framework.Crpw6aS5.js";const c=JSON.parse('{"title":"TaskNotes 新手指南","description":"","frontmatter":{},"headers":[],"relativePath":"TaskNotes/Start Here.md","filePath":"TaskNotes/Start Here.md","lastUpdated":1786608187000}'),l={name:"TaskNotes/Start Here.md"};function r(i,a,n,d,h,p){return s(),t("div",null,[...a[0]||(a[0]=[o(`<h1 id="tasknotes-新手指南" tabindex="-1">TaskNotes 新手指南 <a class="header-anchor" href="#tasknotes-新手指南" aria-label="Permalink to &quot;TaskNotes 新手指南&quot;">​</a></h1> <p>这篇笔记是 TaskNotes 在你仓库里的一次小导览。直接在下面边读边试，之后可以留作参考，也可以等用熟了删掉。</p> <p>TaskNotes 用起来最顺手的时候，是这三件事串成了一条线：</p> <ol><li>快速记下一件事。</li> <li>把它当作一条普通的 Markdown 笔记存下来。</li> <li>通过 Bases 视图来查看和回顾。</li></ol> <h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2> <ul><li>[ ] 启用 Obsidian 自带的 <strong>Bases</strong> 核心插件。</li> <li>[ ] 确认 TaskNotes 已经在 <code>TaskNotes/Views/</code> 下生成了默认的 <code>.base</code> 文件。</li> <li>[ ] 打开命令面板，执行 <strong>TaskNotes: Open tasks view</strong>。</li></ul> <p>只要开启了 <strong>Auto-create default files</strong>，TaskNotes 启动时会自动补上缺失的默认 <code>.base</code> 文件。如果文件仍然没出现，走 <strong>设置 -&gt; TaskNotes -&gt; General -&gt; Views &amp; base files -&gt; Create files</strong> 手动生成。</p> <h2 id="_1-从命令面板创建一个任务" tabindex="-1">1. 从命令面板创建一个任务 <a class="header-anchor" href="#_1-从命令面板创建一个任务" aria-label="Permalink to &quot;1. 从命令面板创建一个任务&quot;">​</a></h2> <p>执行 <strong>TaskNotes: Create new task</strong>，随手建一件你近期打算做的事。</p> <p>标题可以试试这样：</p> <div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Review my TaskNotes setup tomorrow #admin</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>保存后，TaskNotes 会为这条任务生成一条 Markdown 笔记。打开它，看看顶部的 YAML 属性——Bases 正是读这些属性来做筛选、排序、分组，以及把任务放到日历对应位置的。</p> <h2 id="_2-把行内任务转成-tasknote" tabindex="-1">2. 把行内任务转成 TaskNote <a class="header-anchor" href="#_2-把行内任务转成-tasknote" aria-label="Permalink to &quot;2. 把行内任务转成 TaskNote&quot;">​</a></h2> <p>下面这几个勾选项就是普通的 Markdown 任务。用每行上的行内操作，或者命令面板，把它们逐条转成 TaskNote。</p> <ul><li>[ ] Create a TaskNotes inbox task due tomorrow #admin</li> <li>[ ] Schedule a 20 minute planning task for next Monday #planning</li> <li>[ ] Make a task linked to an active project note</li></ul> <p>转换之后，留意几件事：</p> <ul><li>原来那行可以留在这篇笔记里作为上下文。</li> <li>真正的任务此时已经是一条独立的 Markdown 笔记，可以出现在 TaskNotes 的各个视图里了。</li> <li>转换后的那行会带上指向 TaskNote 的链接。右键点这个链接打开任务菜单，试着改一个属性，比如状态、优先级、截止日期、计划日期，或者所属项目。</li></ul> <h2 id="_3-查看你的任务" tabindex="-1">3. 查看你的任务 <a class="header-anchor" href="#_3-查看你的任务" aria-label="Permalink to &quot;3. 查看你的任务&quot;">​</a></h2> <p>下面这些嵌入视图用的是 TaskNotes 默认的 Bases 文件。</p> <h3 id="任务列表" tabindex="-1">任务列表 <a class="header-anchor" href="#任务列表" aria-label="Permalink to &quot;任务列表&quot;">​</a></h3> <p>![[TaskNotes/Views/tasks-default.base]]</p> <p>想要一条清爽的、列出所有未完成任务的列表时，用这个。</p> <h3 id="日程" tabindex="-1">日程 <a class="header-anchor" href="#日程" aria-label="Permalink to &quot;日程&quot;">​</a></h3> <p>![[TaskNotes/Views/agenda-default.base]]</p> <p>当你关心截止日期、计划日期，以及哪些事很快需要关注时，用这个。</p> <h3 id="迷你日历" tabindex="-1">迷你日历 <a class="header-anchor" href="#迷你日历" aria-label="Permalink to &quot;迷你日历&quot;">​</a></h3> <p>![[TaskNotes/Views/mini-calendar-default.base]]</p> <p>想在笔记旁边放一个紧凑的小日历时，用这个。</p> <h3 id="日历" tabindex="-1">日历 <a class="header-anchor" href="#日历" aria-label="Permalink to &quot;日历&quot;">​</a></h3> <p>![[TaskNotes/Views/calendar-default.base]]</p> <p>想要一个更大的日历，来看计划安排、截止日期、时间块和日程事件时，用这个。</p> <h3 id="看板" tabindex="-1">看板 <a class="header-anchor" href="#看板" aria-label="Permalink to &quot;看板&quot;">​</a></h3> <p>![[TaskNotes/Views/kanban-default.base]]</p> <p>想按状态（未开始、进行中、已完成）把工作在不同列之间推动时，用这个。</p> <h2 id="_4-只动那些挡路的地方" tabindex="-1">4. 只动那些挡路的地方 <a class="header-anchor" href="#_4-只动那些挡路的地方" aria-label="Permalink to &quot;4. 只动那些挡路的地方&quot;">​</a></h2> <p>默认配置足够上手。等你清楚自己想改什么了，再去翻这些设置：</p> <ul><li>任务文件存错了位置，看 <strong>设置 -&gt; TaskNotes -&gt; General</strong>。</li> <li>行内任务转换后想存到别处，看 <strong>设置 -&gt; TaskNotes -&gt; Inline Task Settings</strong>。</li> <li>任务弹窗里显示得太多或太少，看 <strong>设置 -&gt; TaskNotes -&gt; Modal Fields</strong>。</li> <li>你仓库用了不同的属性名、状态、优先级或自定义字段，看 <strong>设置 -&gt; TaskNotes -&gt; Task Properties</strong>。</li></ul> <h2 id="_5-变成你自己的" tabindex="-1">5. 变成你自己的 <a class="header-anchor" href="#_5-变成你自己的" aria-label="Permalink to &quot;5. 变成你自己的&quot;">​</a></h2> <p>试着给一条任务加一个自定义属性，比如 <code>energy</code>（精力）、<code>client</code>（客户）或 <code>area</code>（领域）。因为任务本身就是 Markdown 笔记，自定义属性可以直接在 Bases 里用，不需要把你绑死在一套独立的任务数据库上。</p> <h2 id="_6-上下文视图" tabindex="-1">6. 上下文视图 <a class="header-anchor" href="#_6-上下文视图" aria-label="Permalink to &quot;6. 上下文视图&quot;">​</a></h2> <p>Bases 视图可以嵌进日记、项目笔记、会议纪要，或者任务笔记里。Bases 的高级过滤器能把当前笔记当作上下文，于是同一个视图，嵌到哪篇笔记里，就显示跟那篇笔记相关的任务。</p> <p>TaskNotes 的任务笔记里那个 Relationships（关联）小组件就是这套用法。等你打算自定义视图了，去翻 TaskNotes 文档里的示例。</p> <p>几个值得一试的进阶玩法：</p> <ul><li>复制一份 <code>TaskNotes/Views/tasks-default.base</code>，给某个项目单做一个视图。</li> <li>给某个 Base 视图加一个分组，比如按状态或优先级。</li> <li>加一个过滤器，只看本周到期的事。</li> <li>把一条任务关联到项目笔记，再用反向链接看它在哪些地方被提到。</li></ul> <h2 id="更多帮助与扩展" tabindex="-1">更多帮助与扩展 <a class="header-anchor" href="#更多帮助与扩展" aria-label="Permalink to &quot;更多帮助与扩展&quot;">​</a></h2> <ul><li>官方文档：<a href="https://tasknotes.dev/" target="_blank" rel="noreferrer">tasknotes.dev</a></li> <li>反馈问题或 bug：<a href="https://github.com/callumalpass/tasknotes/issues" target="_blank" rel="noreferrer">在 GitHub 开 issue</a></li> <li>配套插件：
<ul><li><a href="https://tasknotes.dev/companion-plugins/canvas-bases/" target="_blank" rel="noreferrer">Canvas Bases</a> 给 Bases 视图加上画布式的看板和 JSON Canvas 快照，可选配 TaskNotes 的徽标、操作和关联连线。</li> <li><a href="https://tasknotes.dev/companion-plugins/tasknotes-workflows/" target="_blank" rel="noreferrer">TaskNotes Workflows</a> 用 Markdown 定义自动化，覆盖 TaskNotes 的事件、计划、手动命令和任务操作。</li></ul></li></ul> <h2 id="就这些" tabindex="-1">就这些 <a class="header-anchor" href="#就这些" aria-label="Permalink to &quot;就这些&quot;">​</a></h2> <p>核心思路你已经摸到了：任务就是笔记，属性让它们可查询，Bases 把它们变成视图。</p>`,94)])])}const u=e(l,[["render",r]]);export{c as __pageData,u as default};
